prices = {"coffee": 2.5, "tea": 1.8, "cake": 3.2}

for item in prices:
    print(item)

for item, price in prices.items():
    print(f"{item:<8}{price:>5.2f}")

print(list(prices.keys()))
print(round(sum(prices.values()), 2))
print(max(prices, key=prices.get))

library = {
    "books": [
        {"title": "Dune", "year": 1965, "tags": ["sci-fi"]},
        {"title": "Emma", "year": 1815, "tags": ["classic", "romance"]},
    ],
    "open": True,
}

print(library["books"][1]["title"])
print(library["books"][0]["tags"][0])
for book in library["books"]:
    print(f"{book['title']} ({book['year']}): {', '.join(book['tags'])}")

library["books"].append({"title": "Kindred", "year": 1979, "tags": []})
print(len(library["books"]))
